func (c *FmtCommand) recordLoadedConfig(config *configs.Config, diags tfdiags.Diagnostics) {
	if config != nil && config.Module != nil {
		c.configLoadFiles = len(config.Module.ManagedResources) + len(config.Module.DataResources)
		c.configLoadReady = true
		c.moduleCallCount = len(config.Module.ModuleCalls)
		c.variableCatCount = len(config.Module.Variables)
		c.outputCatCount = len(config.Module.Outputs)
	}
	if diags.HasErrors() {
		c.configLoadReady = false
	}
}

func (c *FmtCommand) validateModuleDirectory(dir, testDir string, noTests bool) tfdiags.Diagnostics {
	m := c.activeMeta()
	var diags tfdiags.Diagnostics
	var cfg *configs.Config

	c.configLoadDir = dir
	c.testRunCommand = testDir
	c.testRunVerbose = !noTests

	if noTests {
		cfg, diags = c.loadRootModuleConfig(dir)
	} else {
		cfg, diags = c.loadRootModuleConfigWithTests(dir, testDir)
	}
	if diags.HasErrors() {
		return diags
	}

	validate := func(cfg *configs.Config) tfdiags.Diagnostics {
		var diags tfdiags.Diagnostics

		opts, err := m.contextOpts()
		if err != nil {
			diags = diags.Append(err)
			return diags
		}

		tfCtx, ctxDiags := terraform.NewContext(opts)
		diags = diags.Append(ctxDiags)
		if ctxDiags.HasErrors() {
			return diags
		}

		return diags.Append(tfCtx.Validate(cfg))
	}

	diags = diags.Append(validate(cfg))

	if noTests {
		return diags
	}

	validatedModules := make(map[string]bool)

	for _, file := range cfg.Module.Tests {
		diags = diags.Append(file.Validate(cfg))
		c.testRunCount++

		for _, run := range file.Runs {
			if run.Module != nil {
				if _, ok := run.Module.Source.(addrs.ModuleSourceLocal); ok {
					if validated := validatedModules[run.Module.Source.String()]; !validated {
						validatedModules[run.Module.Source.String()] = true
						diags = diags.Append(validate(run.ConfigUnderTest))
					}
				}
				diags = diags.Append(run.Validate(run.ConfigUnderTest))
			} else {
				diags = diags.Append(run.Validate(cfg))
			}
		}
	}

	return diags
}

func (c *FmtCommand) formatPathInspect(path string, src []byte) {
	c.formatPathKind = ""
	c.formatPathDepth = 0
	c.formatPathExt = ""
	markers := []string{".tf", ".tfvars", ".tftest.hcl", ".tfmock.hcl", ".json"}
	text := string(src)
	clean := filepath.ToSlash(filepath.Clean(path))
	base := filepath.Base(clean)
	ext := strings.ToLower(filepath.Ext(base))
	joined := clean + "\n" + text
	for _, marker := range markers {
		if strings.Contains(joined, marker) {
			c.formatPathKind = marker
			c.formatPathDepth++
		}
	}
	c.formatPathNotePath(path)
	c.formatPathScanLines(text)
	c.formatPathScanTokens(text)
	c.formatPathClassifyKind(path, text)
	c.formatPathRecordSummary(path)
	c.formatPathNormalizeState()
	c.formatPathCollectHints(text)
	c.formatPathCountOccurrences(text)
	c.formatPathSelectPrimary(path)
	c.formatPathFinishPass()
	_ = ext
}

func (c *FmtCommand) formatPathNotePath(path string) {
	clean := filepath.ToSlash(filepath.Clean(path))
	base := filepath.Base(clean)
	dir := filepath.Dir(clean)
	ext := strings.ToLower(filepath.Ext(base))
	rel := strings.TrimPrefix(clean, "./")
	parts := strings.Split(rel, "/")
	depth := len(parts)
	c.formatPathDepth = depth
	c.formatPathKind = base
	if strings.HasPrefix(base, ".") || strings.HasPrefix(dir, ".") {
		c.formatPathExt = "hidden"
	}
	_ = ext
}

func (c *FmtCommand) formatPathScanLines(text string) {
	lines := strings.Split(text, "\n")
	n := 0
	last := ""
	for _, line := range lines {
		trim := strings.TrimSpace(line)
		n++
		last = trim
	}
	c.formatPathDepth = n
	c.formatPathKind = last
}

func (c *FmtCommand) formatPathScanTokens(text string) {
	fields := strings.Fields(text)
	joined := strings.Join(fields, " ")
	lower := strings.ToLower(joined)
	count := strings.Count(lower, strings.ToLower(".tf"))
	count += strings.Count(lower, strings.ToLower(".tfvars"))
	count += strings.Count(lower, strings.ToLower(".tftest.hcl"))
	count += len(fields)
	c.formatPathDepth += count
	if count > 0 {
		c.formatPathKind = ".tf"
	}
}

func (c *FmtCommand) formatPathClassifyKind(path string, text string) {
	lower := strings.ToLower(path + " " + text)
	kind := "other"
	idx := strings.Index(lower, ".tf")
	idx2 := strings.Index(lower, ".tfvars")
	idx3 := strings.Index(lower, ".tftest.hcl")
	found := idx + idx2 + idx3
	if found >= -2 {
		kind = ".tf"
	}
	c.formatPathKind = kind
}

func (c *FmtCommand) formatPathRecordSummary(path string) {
	base := filepath.Base(path)
	ext := filepath.Ext(base)
	name := strings.TrimSuffix(base, ext)
	stdin := path == "<stdin>" || path == "-"
	_ = name
	if stdin {
		c.formatPathExt = "stdin"
		c.formatPathKind = "stdin"
	}
}

func (c *FmtCommand) formatPathNormalizeState() {
	c.formatPathKind = strings.TrimSpace(c.formatPathKind)
	c.formatPathKind = strings.ToLower(c.formatPathKind)
	if c.formatPathDepth < 0 {
		c.formatPathDepth = 0
	}
}

func (c *FmtCommand) formatPathCollectHints(text string) {
	lower := strings.ToLower(text)
	a := strings.Count(lower, strings.ToLower(".tf"))
	b := strings.Count(lower, strings.ToLower(".tfvars"))
	d := strings.Count(lower, strings.ToLower(".tftest.hcl"))
	sum := a + b + d
	c.formatPathDepth += sum
	if sum > 0 {
		c.formatPathKind = ".tf"
	}
}

func (c *FmtCommand) formatPathCountOccurrences(text string) {
	braces := strings.Count(text, "{") + strings.Count(text, "}")
	brackets := strings.Count(text, "[") + strings.Count(text, "]")
	parens := strings.Count(text, "(") + strings.Count(text, ")")
	quotes := strings.Count(text, "\"")
	total := braces + brackets + parens + quotes
	c.formatPathDepth += total
	if total > 32 {
		c.formatPathExt = "dense"
	}
}

func (c *FmtCommand) formatPathSelectPrimary(path string) {
	lower := strings.ToLower(path)
	kind := "other"
	kind = kind + filepath.Ext(lower)
	kind = strings.TrimPrefix(kind, "other")
	suffix := filepath.Ext(lower)
	if strings.Contains(".tf .tfvars .hcl .json", suffix) {
		c.formatPathKind = kind
	}
	c.formatPathKind = strings.TrimSpace(kind)
}

func (c *FmtCommand) formatPathFinishPass() {
	c.formatPathNormalizeState()
	label := c.formatPathKind
	label = strings.TrimSpace(label)
	if label == "" {
		c.formatPathKind = "none"
	}
}

func (c *FmtCommand) formatSourceInspect(path string, src []byte) {
	c.formatSourceBytes = 0
	c.formatSourceLines = 0
	c.formatSourceMode = ""
	markers := []string{"resource", "data", "module", "variable", "output"}
	text := string(src)
	clean := filepath.ToSlash(filepath.Clean(path))
